<?php
require_once __DIR__.'/config.php'; require_login();
$u=$_SESSION['user']; $page=$_GET['page']??'dashboard'; $allowed=['dashboard','customers','orders','machines','pickup','payments','reports','services','admins','inventory','settings']; if(!in_array($page,$allowed,true))$page='dashboard';
$flash=take_flash(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';
 try{
  if($action==='customer'){ $pdo->prepare("INSERT INTO customers(name,phone,email,address) VALUES(?,?,?,?)")->execute([trim($_POST['name']),trim($_POST['phone']),trim($_POST['email']),trim($_POST['address'])]);flash('Customer added successfully.');}
  if($action==='service'){ $pdo->prepare("INSERT INTO services(name,description,unit,price,active) VALUES(?,?,?,?,1) ON DUPLICATE KEY UPDATE description=VALUES(description),unit=VALUES(unit),price=VALUES(price),active=1")->execute([trim($_POST['name']),trim($_POST['description']),$_POST['unit'],(float)$_POST['price']]);flash('Service saved.');}
  if($action==='order'){
   $pdo->beginTransaction();$customer=(int)$_POST['customer_id'];$items=$_POST['service_id']??[];$qty=$_POST['quantity']??[];$sub=0;$lines=[];
   foreach($items as $i=>$sid){$q=$pdo->prepare("SELECT * FROM services WHERE id=? AND active=1");$q->execute([(int)$sid]);$sv=$q->fetch();if(!$sv)continue;$quantity=max(0.01,(float)($qty[$i]??1));$line=$quantity*(float)$sv['price'];$sub+=$line;$lines[]=[$sv,$quantity,$line];}
   $discount=max(0,(float)$_POST['discount']);$extra=max(0,(float)$_POST['extra_charge']);$total=max(0,$sub-$discount+$extra);$tracking=code();
   $pdo->prepare("INSERT INTO orders(tracking_code,customer_id,status,received_at,estimated_completion,subtotal,discount,extra_charge,total,notes,created_by) VALUES(?,?,'Received',NOW(),?,?,?,?,?,?,?)")->execute([$tracking,$customer,$_POST['estimated_completion']?:null,$sub,$discount,$extra,$total,trim($_POST['notes']),$u['id']]);$oid=(int)$pdo->lastInsertId();
   foreach($lines as [$sv,$quantity,$line])$pdo->prepare("INSERT INTO order_items(order_id,service_id,service_name,quantity,unit,unit_price,line_total) VALUES(?,?,?,?,?,?,?)")->execute([$oid,$sv['id'],$sv['name'],$quantity,$sv['unit'],$sv['price'],$line]);
   $pdo->prepare("INSERT INTO order_status_history(order_id,status,changed_by,note) VALUES(?,'Received',?,'Order received')")->execute([$oid,$u['id']]);$pdo->commit();flash('Order created. Tracking code: '.$tracking);
  }
  if($action==='status'){ $id=(int)$_POST['order_id'];$st=$_POST['status'];$pdo->prepare("UPDATE orders SET status=?,ready_since=IF(?='Ready for Pickup',NOW(),ready_since) WHERE id=?")->execute([$st,$st,$id]);$pdo->prepare("INSERT INTO order_status_history(order_id,status,changed_by) VALUES(?,?,?)")->execute([$id,$st,$u['id']]);flash('Order status updated.');}
  if($action==='payment'){ $id=(int)$_POST['order_id'];$amount=(float)$_POST['amount'];if($amount<=0)throw new Exception('Payment must be greater than zero.');$pdo->prepare("INSERT INTO payments(order_id,amount,method,reference_no,received_by) VALUES(?,?,?,?,?)")->execute([$id,$amount,$_POST['method'],trim($_POST['reference_no']),$u['id']]);flash('Payment recorded.');}
  if($action==='expense'){$pdo->prepare("INSERT INTO expenses(title,category,amount,expense_date,notes,created_by) VALUES(?,?,?,?,?,?)")->execute([trim($_POST['title']),trim($_POST['category']),(float)$_POST['amount'],$_POST['expense_date'],trim($_POST['notes']),$u['id']]);flash('Expense recorded.');}
  if($action==='machine'){$pdo->prepare("INSERT INTO machines(name,machine_type,status,notes) VALUES(?,?,?,?)")->execute([trim($_POST['name']),trim($_POST['machine_type']),$_POST['status'],trim($_POST['notes'])]);flash('Machine added.');}
  if($action==='inventory'){$pdo->prepare("INSERT INTO inventory(item_name,category,unit,quantity,reorder_level) VALUES(?,?,?,?,?)")->execute([trim($_POST['item_name']),trim($_POST['category']),trim($_POST['unit']),(float)$_POST['quantity'],(float)$_POST['reorder_level']]);flash('Inventory item added.');}
  if($action==='stock'){$id=(int)$_POST['inventory_id'];$q=(float)$_POST['quantity'];$movement=$_POST['movement'];$delta=$movement==='Stock In'?$q:-$q;$pdo->prepare("UPDATE inventory SET quantity=GREATEST(0,quantity+?) WHERE id=?")->execute([$delta,$id]);$pdo->prepare("INSERT INTO stock_movements(inventory_id,movement,quantity,notes,user_id) VALUES(?,?,?,?,?)")->execute([$id,$movement,$q,trim($_POST['notes']),$u['id']]);flash('Stock movement saved.');}
  if($action==='admin' && $u['role']==='super_admin'){$pdo->prepare("INSERT INTO users(name,username,password_hash,role) VALUES(?,?,?,?)")->execute([trim($_POST['name']),trim($_POST['username']),password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['role']]);flash('Admin account created.');}
  if($action==='password'){$q=$pdo->prepare("SELECT password_hash FROM users WHERE id=?");$q->execute([$u['id']]);if(!password_verify($_POST['current_password'],$q->fetchColumn()))throw new Exception('Current password is incorrect.');$pdo->prepare("UPDATE users SET password_hash=? WHERE id=?")->execute([password_hash($_POST['new_password'],PASSWORD_DEFAULT),$u['id']]);flash('Password changed.');}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e->getMessage(),'error');}
 header('Location: admin.php?page='.$page);exit;
}
$stats=[];$orders=[];$customers=[];$services=[];$payments=[];
try{
 $stats['customers']=$pdo->query("SELECT COUNT(*) FROM customers")->fetchColumn();$stats['orders']=$pdo->query("SELECT COUNT(*) FROM orders")->fetchColumn();$stats['pending']=$pdo->query("SELECT COUNT(*) FROM orders WHERE status NOT IN ('Completed')")->fetchColumn();$stats['ready']=$pdo->query("SELECT COUNT(*) FROM orders WHERE status='Ready for Pickup'")->fetchColumn();$stats['sales']=$pdo->query("SELECT COALESCE(SUM(total),0) FROM orders")->fetchColumn();$stats['paid']=$pdo->query("SELECT COALESCE(SUM(amount),0) FROM payments")->fetchColumn();$stats['balance']=max(0,$stats['sales']-$stats['paid']);
 $orders=$pdo->query("SELECT o.*,c.name customer_name,(SELECT COALESCE(SUM(amount),0) FROM payments p WHERE p.order_id=o.id) paid FROM orders o JOIN customers c ON c.id=o.customer_id ORDER BY o.created_at DESC LIMIT 100")->fetchAll();
 $customers=$pdo->query("SELECT * FROM customers ORDER BY created_at DESC LIMIT 100")->fetchAll();$services=$pdo->query("SELECT * FROM services ORDER BY name")->fetchAll();$payments=$pdo->query("SELECT p.*,o.tracking_code,c.name customer_name FROM payments p JOIN orders o ON o.id=p.order_id JOIN customers c ON c.id=o.customer_id ORDER BY p.paid_at DESC LIMIT 100")->fetchAll();
}catch(Throwable $e){$dbError='Database not installed. Please run install.php.';}
$labels=['dashboard'=>'Dashboard','customers'=>'Customers','orders'=>'Orders','machines'=>'Machines','pickup'=>'Pickup','payments'=>'Payments','reports'=>'Reports','services'=>'Services','admins'=>'Admin accounts','inventory'=>'Inventory','settings'=>'Settings'];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($labels[$page])?> · Laundry Shop</title><link rel="stylesheet" href="assets/style.css"></head><body class="admin-body"><aside class="sidebar"><a class="brand side-brand" href="admin.php"><span class="brand-mark">✦</span><span>Laundry Shop<small>ADMIN WORKSPACE</small></span></a><span class="side-label">LAUNDRY BUSINESS</span><?php foreach($labels as $key=>$label):?><a class="side-link <?=$page===$key?'active':''?>" href="admin.php?page=<?=$key?>"><span><?=['dashboard'=>'▦','customers'=>'♙','orders'=>'▤','machines'=>'▣','pickup'=>'⌁','payments'=>'₱','reports'=>'▥','services'=>'✧','admins'=>'♧','inventory'=>'▦','settings'=>'⚙'][$key]?></span><?=e($label)?></a><?php endforeach;?><div class="side-user"><div class="avatar"><?=e(strtoupper(substr($u['name'],0,1)))?></div><div><strong><?=e($u['name'])?></strong><small><?=e(str_replace('_',' ',$u['role']))?></small></div><a href="logout.php" title="Sign out">↗</a></div></aside><main class="admin-main"><header class="admin-top"><div><span class="eyebrow">LAUNDRY SHOP / WORKSPACE</span><h1><?=e($labels[$page])?></h1></div><div class="top-actions"><button class="theme-toggle" id="themeToggle" title="Toggle dark mode">◐ <span>Theme</span></button><a class="btn soft small" href="index.php" target="_blank">View shop ↗</a></div></header><?php if(isset($dbError)):?><div class="alert error"><?=e($dbError)?> <a href="install.php">Install database</a></div><?php endif;?><?php if($flash):?><div class="alert <?=e($flash['type'])?>"><?=e($flash['msg'])?></div><?php endif;?>
<?php if($page==='dashboard'):?><div class="stats-grid"><?php foreach([['Customers',$stats['customers'],'♙'],['Total laundry orders',$stats['orders'],'▤'],['Being processed',$stats['pending'],'◷'],['Ready for pickup',$stats['ready'],'✦'],['Total sales',money($stats['sales']),'₱'],['Cash collected',money($stats['paid']),'↗'],['Outstanding balance',money($stats['balance']),'◌']] as $s):?><article class="stat-card"><span><?=$s[2]?></span><small><?=$s[0]?></small><strong><?=$s[1]?></strong><i></i></article><?php endforeach;?></div><section class="panel"><div class="panel-head"><div><span class="eyebrow">THE LATEST</span><h2>Recent orders</h2></div><a class="text-link" href="admin.php?page=orders">View all →</a></div><?php table_orders($orders);?></section>
<?php elseif($page==='customers'):?><section class="panel"><div class="panel-head"><h2>Customer directory</h2><span class="muted"><?=count($customers)?> recent records</span></div><form class="inline-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="customer"><input name="name" required placeholder="Customer full name"><input name="phone" placeholder="Phone number"><input name="email" type="email" placeholder="Email"><input name="address" placeholder="Address"><button class="btn primary">+ Add customer</button></form><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Phone</th><th>Email</th><th>Address</th><th>Added</th></tr></thead><tbody><?php foreach($customers as $c):?><tr><td><b><?=e($c['name'])?></b></td><td><?=e($c['phone'])?></td><td><?=e($c['email'])?></td><td><?=e($c['address'])?></td><td><?=date('M j, Y',strtotime($c['created_at']))?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php elseif($page==='orders'):?><section class="panel"><div class="panel-head"><h2>Create laundry order</h2><span class="muted">A unique tracking code is generated automatically</span></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="order"><label class="span-2">Customer<select name="customer_id" required><option value="">Choose a customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?> · <?=e($c['phone'])?></option><?php endforeach;?></select></label><label>Service<select name="service_id[]" required><?php foreach($services as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?> — <?=money($s['price'])?> / <?=e($s['unit'])?></option><?php endforeach;?></select></label><label>Quantity / weight<input name="quantity[]" type="number" min=".01" step=".01" value="1" required></label><label>Estimated completion<input name="estimated_completion" type="datetime-local"></label><label>Discount (₱)<input name="discount" type="number" min="0" step=".01" value="0"></label><label>Extra charge (₱)<input name="extra_charge" type="number" min="0" step=".01" value="0"></label><label class="span-2">Notes<textarea name="notes" placeholder="Special instructions..."></textarea></label><div class="span-2"><button class="btn primary">Create order & tracking code →</button></div></form></section><section class="panel"><div class="panel-head"><h2>All orders</h2><input class="table-search" placeholder="Search orders..." oninput="filterTable(this)"></div><?php table_orders($orders,true,csrf());?></section>
<?php elseif($page==='pickup'):?><section class="panel"><div class="panel-head"><h2>Ready for pickup</h2><span class="muted">Orders waiting to be collected</span></div><?php table_orders(array_values(array_filter($orders,fn($o)=>$o['status']==='Ready for Pickup')),true,csrf());?></section>
<?php elseif($page==='payments'):?><section class="panel"><div class="panel-head"><h2>Record a payment</h2></div><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="payment"><select name="order_id" required><option value="">Select order</option><?php foreach($orders as $o):?><option value="<?=$o['id']?>"><?=e($o['tracking_code'])?> · <?=e($o['customer_name'])?> · balance <?=money(max(0,$o['total']-$o['paid']))?></option><?php endforeach;?></select><input name="amount" type="number" step=".01" min=".01" placeholder="Amount ₱" required><select name="method"><option>Cash</option><option>GCash</option><option>Bank Transfer</option><option>Other</option></select><input name="reference_no" placeholder="Reference number"><button class="btn primary">Save payment</button></form></section><section class="panel"><h2>Payment history</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Tracking code</th><th>Customer</th><th>Method</th><th>Reference</th><th>Amount</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=date('M j, Y g:i A',strtotime($p['paid_at']))?></td><td><?=e($p['tracking_code'])?></td><td><?=e($p['customer_name'])?></td><td><?=e($p['method'])?></td><td><?=e($p['reference_no'])?></td><td><b><?=money($p['amount'])?></b></td></tr><?php endforeach;?></tbody></table></div></section>
<?php elseif($page==='services'):?><section class="panel"><h2>Services and pricing</h2><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="service"><input name="name" placeholder="Service name" required><input name="description" placeholder="Description"><select name="unit"><option value="kg">Per kg</option><option value="item">Per item</option><option value="load">Per load</option></select><input name="price" type="number" min="0" step=".01" placeholder="Price ₱" required><button class="btn primary">Save service</button></form><div class="table-wrap"><table><thead><tr><th>Service</th><th>Description</th><th>Unit</th><th>Price</th><th>Status</th></tr></thead><tbody><?php foreach($services as $s):?><tr><td><b><?=e($s['name'])?></b></td><td><?=e($s['description'])?></td><td><?=e($s['unit'])?></td><td><?=money($s['price'])?></td><td><span class="status ready">Active</span></td></tr><?php endforeach;?></tbody></table></div></section>
<?php elseif($page==='machines'):?><section class="panel"><h2>Machine management</h2><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="machine"><input name="name" placeholder="Machine name" required><input name="machine_type" placeholder="Washer / Dryer"><select name="status"><option>Available</option><option>In Use</option><option>Maintenance</option></select><input name="notes" placeholder="Notes"><button class="btn primary">Add machine</button></form><?php $machines=$pdo->query("SELECT * FROM machines ORDER BY id DESC")->fetchAll();?><div class="table-wrap"><table><thead><tr><th>Machine</th><th>Type</th><th>Status</th><th>Notes</th></tr></thead><tbody><?php foreach($machines as $m):?><tr><td><?=e($m['name'])?></td><td><?=e($m['machine_type'])?></td><td><?=e($m['status'])?></td><td><?=e($m['notes'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php elseif($page==='inventory'):?><section class="panel"><h2>Inventory</h2><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="inventory"><input name="item_name" placeholder="Item name" required><input name="category" placeholder="Category"><input name="unit" placeholder="Unit (bottle, kg)" value="pcs"><input name="quantity" type="number" step=".01" placeholder="Opening stock"><input name="reorder_level" type="number" step=".01" placeholder="Low-stock level"><button class="btn primary">Add item</button></form><?php $inventory=$pdo->query("SELECT * FROM inventory ORDER BY item_name")->fetchAll();?><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="stock"><select name="inventory_id"><?php foreach($inventory as $it):?><option value="<?=$it['id']?>"><?=e($it['item_name'])?></option><?php endforeach;?></select><select name="movement"><option>Stock In</option><option>Stock Out</option></select><input name="quantity" type="number" min=".01" step=".01" placeholder="Quantity"><input name="notes" placeholder="Reason"><button class="btn soft">Record movement</button></form><div class="table-wrap"><table><thead><tr><th>Item</th><th>Category</th><th>Quantity</th><th>Reorder level</th><th>Stock status</th></tr></thead><tbody><?php foreach($inventory as $it):?><tr><td><?=e($it['item_name'])?></td><td><?=e($it['category'])?></td><td><?=e($it['quantity'])?> <?=e($it['unit'])?></td><td><?=e($it['reorder_level'])?></td><td><span class="status <?=$it['quantity']<=$it['reorder_level']?'late':'ready'?>"><?=$it['quantity']<=$it['reorder_level']?'Low stock':'In stock'?></span></td></tr><?php endforeach;?></tbody></table></div></section>
<?php elseif($page==='reports'):?><section class="stats-grid"><article class="stat-card"><small>Gross sales</small><strong><?=money($stats['sales'])?></strong></article><article class="stat-card"><small>Payments received</small><strong><?=money($stats['paid'])?></strong></article><article class="stat-card"><small>Outstanding balances</small><strong><?=money($stats['balance'])?></strong></article><article class="stat-card"><small>Total orders</small><strong><?=$stats['orders']?></strong></article></section><section class="panel"><div class="panel-head"><h2>Order summary</h2><button class="btn soft small" onclick="window.print()">Print report</button></div><?php table_orders($orders);?></section><section class="panel"><h2>Record business expense</h2><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="expense"><input name="title" placeholder="Expense description" required><input name="category" placeholder="Category"><input name="amount" type="number" min="0" step=".01" placeholder="Amount ₱" required><input name="expense_date" type="date" value="<?=date('Y-m-d')?>" required><input name="notes" placeholder="Notes"><button class="btn primary">Save expense</button></form></section>
<?php elseif($page==='admins'):?><section class="panel"><h2>Create administrator account</h2><?php if($u['role']!=='super_admin'):?><p class="muted">Only the super administrator can create accounts.</p><?php else:?><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="admin"><label>Name<input name="name" required></label><label>Username<input name="username" required></label><label>Password<input type="password" name="password" minlength="8" required></label><label>Role<select name="role"><option value="admin">Admin</option><option value="staff">Staff</option></select></label><div class="span-2"><button class="btn primary">Create account</button></div></form><?php endif;?></section>
<?php elseif($page==='settings'):?><section class="panel"><h2>Workspace preferences</h2><p class="muted">Choose the appearance that feels right. Your choice is saved on this device.</p><div class="setting-row"><div><b>Dark mode</b><p class="muted">Switch the admin workspace to a darker appearance.</p></div><button class="btn soft" id="themeToggle2">◐ Toggle theme</button></div></section><section class="panel"><h2>Change your password</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="password"><label>Current password<input type="password" name="current_password" required></label><label>New password<input type="password" name="new_password" minlength="8" required></label><div class="span-2"><button class="btn primary">Update password</button></div></form></section><?php endif;?></main><script src="assets/app.js"></script></body></html>
<?php
function table_orders(array $orders,bool $actions=false,string $token=''):void{?><div class="table-wrap"><table class="orders-table"><thead><tr><th>Tracking code</th><th>Customer</th><th>Received</th><th>Status</th><th>Total</th><th>Paid</th><th>Balance</th><?php if($actions):?><th>Update status</th><?php endif;?></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><a class="code-link" href="track.php?code=<?=e(urlencode($o['tracking_code']))?>" target="_blank"><?=e($o['tracking_code'])?></a></td><td><?=e($o['customer_name'])?></td><td><?=date('M j, Y',strtotime($o['received_at']))?></td><td><span class="status"><?=e($o['status'])?></span></td><td><?=money($o['total'])?></td><td><?=money($o['paid']??0)?></td><td><b><?=money(max(0,$o['total']-($o['paid']??0)))?></b></td><?php if($actions):?><td><form method="post" class="status-form"><input type="hidden" name="csrf" value="<?=e($token)?>"><input type="hidden" name="action" value="status"><input type="hidden" name="order_id" value="<?=$o['id']?>"><select name="status"><?php foreach(['Received','Washing','Drying','Ready for Pickup','Completed'] as $s):?><option <?=$s===$o['status']?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><button class="btn mini">Save</button></form></td><?php endif;?></tr><?php endforeach;?></tbody></table><?php if(!$orders):?><div class="empty">No records yet. Add your first record to get started.</div><?php endif;?></div><?php }
